const body = $('Booking Availability Webhook').first().json.body ?? {};

function normalizeDate(value) {
  const text = String(value ?? '').trim();
  let match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (match) return `${match[1]}-${match[2].padStart(2, '0')}-${match[3].padStart(2, '0')}`;
  match = text.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (match) return `${match[3]}-${match[1].padStart(2, '0')}-${match[2].padStart(2, '0')}`;
  return text;
}

function normalizeTime(value) {
  const text = String(value ?? '').trim().toUpperCase();
  const match = text.match(/^(\d{1,2})(?::(\d{2}))?\s*(AM|PM)?$/);
  if (!match) return text;
  let hour = Number(match[1]);
  const minute = Number(match[2] ?? 0);
  if (match[3] === 'AM' && hour === 12) hour = 0;
  if (match[3] === 'PM' && hour !== 12) hour += 12;
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

const technicianName = String(body.technician_name ?? '').trim();
const serviceCategory = String(body.service_category ?? '').trim();
const requestedDate = normalizeDate(body.date);
const requestedTime = normalizeTime(body.time);

if (!serviceCategory || !requestedDate || !requestedTime) {
  throw new Error('service_category, date, and time are required.');
}

const rows = $input.all().map((item) => item.json);
const conflict = rows.some((row) => {
  const sameCategory = String(row.service_category ?? '').trim().toLowerCase() === serviceCategory.toLowerCase();
  const sameTechnician = !technicianName || String(row.technician_name ?? '').trim().toLowerCase() === technicianName.toLowerCase();
  return sameCategory && sameTechnician &&
    normalizeDate(row.booking_date) === requestedDate &&
    normalizeTime(row.booking_time) === requestedTime &&
    String(row.status ?? 'confirmed').trim().toLowerCase() !== 'cancelled';
});

return [{ json: {
  available: !conflict,
  technician_name: technicianName || 'Any available technician',
  service_category: serviceCategory,
  date: requestedDate,
  time: requestedTime,
} }];

const body = $('Manage Booking Webhook').first().json.body ?? {};

function normalizePhone(value) {
  const digits = String(value ?? '').replace(/\D/g, '');
  return digits.length > 10 ? digits.slice(-10) : digits;
}

const bookingId = String(body.booking_id ?? '').trim().toUpperCase();
const phone = normalizePhone(body.phone_number);

if (!bookingId || !phone) {
  return [{ json: { found: false, error: 'booking_id or phone_number is missing' } }];
}

const match = $input.all().find(({ json }) =>
  String(json.booking_id ?? '').trim().toUpperCase() === bookingId &&
  normalizePhone(json.phone_number) === phone &&
  String(json.status ?? '').trim().toLowerCase() !== 'cancelled'
);

if (!match) return [{ json: { found: false } }];
return [{ json: { ...match.json, found: true, row_number: match.json.row_number } }];

const body = $('Manage Booking Webhook').first().json.body ?? {};
const original = $input.first().json;
const hasValue = (value) => value !== undefined && value !== null && String(value).trim() !== '';

return [{ json: {
  row_number: original.row_number,
  booking_date: hasValue(body.new_date) ? body.new_date : original.booking_date,
  booking_time: hasValue(body.new_time) ? body.new_time : original.booking_time,
  technician_name: hasValue(body.new_technician_name) ? body.new_technician_name : original.technician_name,
  service_category: hasValue(body.new_service_category) ? body.new_service_category : original.service_category,
  service_address: hasValue(body.new_service_address) ? body.new_service_address : original.service_address,
  status: 'confirmed',
} }];

const body = $input.first().json.body ?? {};
const required = ['customer_name', 'phone_number', 'service_address', 'service_category', 'date', 'time'];
const missing = required.filter((field) => body[field] === undefined || body[field] === null || String(body[field]).trim() === '');
if (missing.length) throw new Error(`Missing required booking fields: ${missing.join(', ')}`);
if (body.caller_confirmed !== true) throw new Error('Booking requires explicit caller confirmation.');
return $input.all();

const body = $input.first().json.body ?? {};
if (!['cancel', 'reschedule'].includes(String(body.action ?? '').toLowerCase())) throw new Error('action must be cancel or reschedule.');
if (!body.booking_id || !body.phone_number) throw new Error('booking_id and phone_number are required.');
if (body.caller_confirmed !== true) throw new Error('Booking changes require explicit caller confirmation.');
if (String(body.action).toLowerCase() === 'reschedule' && (!body.new_date || !body.new_time)) throw new Error('new_date and new_time are required for rescheduling.');
return $input.all();
